?><main id="main"><section class="nob-hero"><div class="nob-container nob-hero-inner"><div class="nob-hero-copy"><span class="nob-kicker"><?php esc_html_e('NotOnlyBook • IGCSE resources','notonlybook-modern'); ?></span><h1><?php echo wp_kses_post(preg_replace('/(IGCSE)/i','<span>$1</span>',esc_html(get_theme_mod('nob_hero_title','Study smarter. Find the right IGCSE resource faster.')),1)); ?></h1><p><?php echo esc_html(get_theme_mod('nob_hero_text','Cambridge resources, books, notes, worksheets and past papers — organised for students, parents and educators.')); ?></p><form class="nob-hero-search" role="search" method="get" action="<?php echo esc_url(home_url('/')); ?>"><label class="screen-reader-text" for="nob-hero-q"><?php esc_html_e('Search resources','notonlybook-modern'); ?></label><input id="nob-hero-q" type="search" name="s" placeholder="<?php esc_attr_e('Search subject, year, paper or topic…','notonlybook-modern'); ?>"><button type="submit"><?php esc_html_e('Search','notonlybook-modern'); ?></button></form><div class="nob-hero-chips" aria-label="<?php esc_attr_e('Popular topics','notonlybook-modern'); ?>"><?php foreach(array_slice($topics,0,4) as $topic): ?><a class="nob-chip" href="<?php echo esc_url(get_term_link($topic)); ?>"><?php echo esc_html($topic->name); ?></a><?php endforeach; ?></div></div><aside class="nob-hero-panel" aria-label="<?php esc_attr_e('Library overview','notonlybook-modern'); ?>"><h2 class="nob-panel-title"><?php esc_html_e('Built around your learning journey','notonlybook-modern'); ?></h2><div class="nob-stat-grid"><div class="nob-stat"><strong><?php echo esc_html(number_format_i18n($published_count)); ?>+</strong><span><?php esc_html_e('published learning resources','notonlybook-modern'); ?></span></div><div class="nob-stat"><strong><?php echo esc_html(number_format_i18n($topic_count)); ?></strong><span><?php esc_html_e('active subject categories','notonlybook-modern'); ?></span></div><div class="nob-stat"><strong><?php echo esc_html(count($years)); ?></strong><span><?php esc_html_e('school-year collections detected','notonlybook-modern'); ?></span></div><div class="nob-stat"><strong>IGCSE</strong><span><?php esc_html_e('past papers, notes and study guidance','notonlybook-modern'); ?></span></div></div></aside></div></section>
<?php if($years): ?><section class="nob-section nob-section--white"><div class="nob-container"><div class="nob-section-head"><div><span class="nob-kicker"><?php esc_html_e('Browse by level','notonlybook-modern'); ?></span><h2><?php esc_html_e('Find resources by school year','notonlybook-modern'); ?></h2></div></div><div class="nob-years"><?php foreach($years as $number=>$category): ?><a class="nob-year" href="<?php echo esc_url(get_term_link($category)); ?>"><span><?php echo esc_html($number); ?></span><?php esc_html_e('Year','notonlybook-modern'); ?></a><?php endforeach; ?></div></div></section><?php endif; ?>
